// HAND-OWNED (quick-log). Not generated by Bubblewrap.
package io.github.palo007.twa.quicklog

import android.app.AlarmManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.os.Build
import android.util.Log
import androidx.core.app.NotificationManagerCompat
import org.json.JSONArray
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale
import java.util.TimeZone

/**
 * Owns the alarms for /inbox-meta/reminders.json items (plan todo 16). `rearm` is the single
 * entry point: called after a sync, on boot, and on TIME_SET/TIMEZONE_CHANGED.
 */
object ReminderScheduler {
    const val ACTION_FIRE = "io.github.palo007.twa.quicklog.ACTION_REMINDER_FIRE"
    const val EXTRA_KEY = "key"
    const val EXTRA_FIRE_AT = "fireAt" // intended fire time (ms); absent on alarms from older APKs

    private const val KEY_ARMED_KEYS = "reminder_armed_keys" // JSON array of item keys
    private const val KEY_LAST_FIRED_SLOT_PREFIX = "reminder_last_fired_" // + key -> slot ms
    private const val TAG = "QuestaReminder"

    /** What `rearm` should do with the stored list: keep the armed alarms, or apply a list. */
    internal sealed class RearmPlan {
        object Keep : RearmPlan()
        data class Apply(val items: List<ReminderItem>, val cancelKeys: Set<String>) : RearmPlan()
    }

    /**
     * Pure decision for `rearm` (JVM-testable, TWA-C1). Nothing stored -> cancel all; stored but
     * unparseable -> Keep (never wipe armed alarms on a bad list); valid list (even empty) -> apply.
     * Known limit: after a reboot the OS has dropped all alarms, so `Keep` cannot re-create them and
     * the armed-key count stays stale until the next good sync. The download path stores only
     * parseable lists, so this needs a stricter parser in a newer APK or corrupt prefs.
     */
    internal fun rearmPlan(text: String?, armedBefore: Set<String>): RearmPlan {
        if (text == null) return RearmPlan.Apply(emptyList(), armedBefore)
        val items = parseReminderList(text) ?: return RearmPlan.Keep
        return RearmPlan.Apply(items, armedBefore - items.map { it.key }.toSet())
    }

    @Synchronized
    fun rearm(ctx: Context) {
        val app = ctx.applicationContext
        val p = DropboxAuth.prefs(app)
        val text = p.getString(ReminderSyncWorker.KEY_REMINDERS_JSON, null)
        val armedBefore = readArmedKeys(p)
        val plan = rearmPlan(text, armedBefore)
        if (plan !is RearmPlan.Apply) {
            Log.w(TAG, "rearm kept: stored list unreadable")
            return
        }
        val items = plan.items
        val collisions = requestCodeCollisions(items.map { it.key })
        if (collisions.isNotEmpty()) Log.w(TAG, "request code collision keys=$collisions")
        val now = System.currentTimeMillis()
        val tz = TimeZone.getDefault()

        // Cancel alarms for keys no longer present.
        val am = alarmManager(app)
        for (staleKey in plan.cancelKeys) {
            am.cancel(pendingIntent(app, staleKey))
        }

        val armedAfter = HashSet<String>()
        for (item in items) {
            val fireAt = nextFireMs(item, now, tz)
            if (fireAt == null) {
                am.cancel(pendingIntent(app, item.key))
                continue
            }
            scheduleAlarm(app, am, item, fireAt)
            armedAfter.add(item.key)
        }
        writeArmedKeys(p, armedAfter)
        Log.i(TAG, "rearm items=${items.size} armed=${armedAfter.size}")
    }

    private fun scheduleAlarm(ctx: Context, am: AlarmManager, item: ReminderItem, fireAt: Long) {
        val pi = pendingIntent(ctx, item.key, fireAt)
        val exact = Build.VERSION.SDK_INT < 31 || am.canScheduleExactAlarms()
        try {
            when {
                Build.VERSION.SDK_INT >= 31 && am.canScheduleExactAlarms() ->
                    am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, fireAt, pi)
                Build.VERSION.SDK_INT >= 31 ->
                    am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, fireAt, pi)
                // API 23-30: exact alarms need no permission.
                Build.VERSION.SDK_INT >= 23 ->
                    am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, fireAt, pi)
                else ->
                    am.setExact(AlarmManager.RTC_WAKEUP, fireAt, pi)
            }
            Log.i(TAG, "armed key=${item.key} -> ${formatLocal(fireAt)} ${if (exact) "exact" else "inexact"}")
        } catch (t: SecurityException) {
            // Exact alarm permission revoked mid-flight: fall back to inexact, still Doze-safe (TWA-A3).
            Log.w(TAG, "exact alarm denied for ${item.key}, using inexact", t)
            if (Build.VERSION.SDK_INT >= 23) {
                am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, fireAt, pi)
            } else {
                am.set(AlarmManager.RTC_WAKEUP, fireAt, pi)
            }
            Log.i(TAG, "armed key=${item.key} -> ${formatLocal(fireAt)} inexact")
        }
    }

    private fun formatLocal(ms: Long): String =
        SimpleDateFormat("yyyy-MM-dd HH:mm", Locale.US).format(Date(ms))

    /** Called by the receiver right after it fires: re-arm just that one item's next slot. */
    @Synchronized // same monitor as rearm: no lost update of the armed-keys set (TWA-A5)
    fun rearmOne(ctx: Context, key: String) {
        // Cheapest correct option: re-derive from the same stored JSON, same as a full rearm,
        // but only touch this key's alarm to avoid perturbing others mid-batch.
        val app = ctx.applicationContext
        val p = DropboxAuth.prefs(app)
        val text = p.getString(ReminderSyncWorker.KEY_REMINDERS_JSON, null) ?: return
        val item = parseReminderList(text)?.firstOrNull { it.key == key } ?: return
        val now = System.currentTimeMillis()
        val fireAt = nextFireMs(item, now, TimeZone.getDefault())
        val am = alarmManager(app)
        if (fireAt == null) {
            am.cancel(pendingIntent(app, key))
            val armed = readArmedKeys(p).toMutableSet()
            armed.remove(key)
            writeArmedKeys(p, armed)
        } else {
            scheduleAlarm(app, am, item, fireAt)
        }
    }

    fun hasExactAlarmPermission(ctx: Context): Boolean =
        Build.VERSION.SDK_INT < 31 || alarmManager(ctx).canScheduleExactAlarms()

    /**
     * True when native alarms can plausibly fire: Dropbox connected, a parsed reminder list is
     * stored, and notifications are enabled. Exact-alarm permission is NOT required here (an
     * inexact alarm still fires, just less precisely). Used by LauncherActivity to decide whether
     * the web app may go silent (`nr=1`) without leaving the user with no reminder at all.
     */
    @JvmStatic
    fun nativeReady(ctx: Context): Boolean {
        return try {
            if (!DropboxAuth.isConnected(ctx)) return false
            val text = DropboxAuth.prefs(ctx).getString(ReminderSyncWorker.KEY_REMINDERS_JSON, null)
                ?: return false
            if (parseReminderList(text) == null) return false
            NotificationManagerCompat.from(ctx).areNotificationsEnabled()
        } catch (t: Throwable) {
            false
        }
    }

    fun lastFiredSlot(ctx: Context, key: String): Long =
        DropboxAuth.prefs(ctx).getLong(KEY_LAST_FIRED_SLOT_PREFIX + key, 0L)

    fun markFiredSlot(ctx: Context, key: String, slotMs: Long) {
        DropboxAuth.prefs(ctx).edit().putLong(KEY_LAST_FIRED_SLOT_PREFIX + key, slotMs).apply()
    }

    fun armedCount(ctx: Context): Int = readArmedKeys(DropboxAuth.prefs(ctx)).size

    private fun alarmManager(ctx: Context): AlarmManager =
        ctx.getSystemService(Context.ALARM_SERVICE) as AlarmManager

    /** Extras do not change PendingIntent identity, so `cancel` (fireAt = 0) still matches. */
    private fun pendingIntent(ctx: Context, key: String, fireAt: Long = 0L): PendingIntent {
        val intent = Intent(ACTION_FIRE).setClass(ctx, ReminderReceiver::class.java)
            .putExtra(EXTRA_KEY, key)
        if (fireAt > 0L) intent.putExtra(EXTRA_FIRE_AT, fireAt)
        val flags = PendingIntent.FLAG_UPDATE_CURRENT or
            (if (Build.VERSION.SDK_INT >= 23) PendingIntent.FLAG_IMMUTABLE else 0)
        return PendingIntent.getBroadcast(ctx, requestCode(key), intent, flags)
    }

    /** Stable, non-zero-colliding-enough request code from the key (32-bit hash is fine here). */
    internal fun requestCode(key: String): Int = key.hashCode()

    /** Keys whose request code is shared with another key (TWA-A7 detector; no id-map change). */
    internal fun requestCodeCollisions(keys: Collection<String>): Set<String> =
        keys.toSet().groupBy { requestCode(it) }.values.filter { it.size > 1 }.flatten().toSet()

    private fun readArmedKeys(p: android.content.SharedPreferences): Set<String> {
        val s = p.getString(KEY_ARMED_KEYS, null) ?: return emptySet()
        return try {
            val arr = JSONArray(s)
            (0 until arr.length()).mapNotNull { arr.optString(it, null) }.toSet()
        } catch (e: Exception) {
            emptySet()
        }
    }

    private fun writeArmedKeys(p: android.content.SharedPreferences, keys: Set<String>) {
        p.edit().putString(KEY_ARMED_KEYS, JSONArray(keys.toList()).toString()).apply()
    }
}
